import{_ as t,o as a,c as s,a3 as o}from"./chunks/framework.D1GAkLkK.js";const u=JSON.parse('{"title":"Compatibility","description":"","frontmatter":{},"headers":[],"relativePath":"reference/compatibility.md","filePath":"reference/compatibility.md"}'),r={name:"reference/compatibility.md"};function n(i,e,d,c,h,l){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h1><p>OpsTruss follows <a href="https://semver.org" target="_blank" rel="noreferrer">Semantic Versioning</a>. Within a major version, such as 1.x, a minor or patch release keeps every project, component, plugin, and script that reads <code>--json</code> working as it did, without a change on their side.</p><h2 id="what-stays" tabindex="-1">What stays <a class="header-anchor" href="#what-stays" aria-label="Permalink to &quot;What stays&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Promised</th></tr></thead><tbody><tr><td>Files</td><td>The keys of <code>opstruss.yaml</code>, <code>opstruss.plugin.yaml</code>, and <code>opstruss.lock</code> and what they mean; built-in tasks; the keywords and functions of expressions</td></tr><tr><td>Command line</td><td>Commands, built-in flags, exit codes, and the JSON of <code>--json</code>: events and documents</td></tr><tr><td>Plugins</td><td>The <a href="./program-contract">program contract</a>: what a program gets and gives</td></tr><tr><td>State</td><td>Records, the <code>_meta</code> of each stack, <code>kv</code>, the file of each daemon, the shape of events, addresses, run ids, and the values of <code>outcome</code></td></tr></tbody></table><h2 id="what-may-change" tabindex="-1">What may change <a class="header-anchor" href="#what-may-change" aria-label="Permalink to &quot;What may change&quot;">​</a></h2><ul><li>What OpsTruss prints for people: the text at a terminal, colors, the layout of lines, and error messages. Scripts read <code>--json</code> instead.</li><li>Where files lie under <code>.opstruss/runs/</code>, <code>logs/</code>, and <code>work/</code>, and the cache in <code>~/.opstruss/</code>.</li><li>The API between the command line and the daemon, which both come from one binary.</li><li>What <code>OPSTRUSS_LOG=debug</code> prints.</li><li>What a version does not support yet, such as backend plugins and <code>mcp:</code>, which it refuses; a later version may support them.</li><li>A fix of a security problem, when nothing else fixes it.</li></ul><h2 id="how-opstruss-changes" tabindex="-1">How OpsTruss changes <a class="header-anchor" href="#how-opstruss-changes" aria-label="Permalink to &quot;How OpsTruss changes&quot;">​</a></h2><ul><li><strong>It adds.</strong> A new key, field, variable, or command is optional, and without it OpsTruss behaves as before. Readers of events, plugins, and OpsTruss itself ignore fields and kinds of events they do not know. <code>outcome</code> keeps its four values; details come in new fields.</li><li><strong>It starts strict.</strong> Validation and limits start narrow and only grow looser, since what a version accepts, a later one accepts too.</li><li><strong>The level in <code>opstruss:</code>.</strong> Each file names the version of OpsTruss it is written for. An older OpsTruss refuses it, and a newer one keeps the behavior of that level for a change that cannot be an addition. The <a href="https://github.com/opstruss/opstruss/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">changelog</a> names each such change.</li><li><strong>Data has versions.</strong> Everything OpsTruss writes has a version. An older OpsTruss refuses data that a newer one wrote, and says to upgrade; a newer one reads every older version and migrates it when it writes.</li></ul><p>A change that breaks what this page promises comes only in a new major version, with its upgrade in the changelog under &quot;Upgrade notes&quot;.</p>',9)])])}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
